import { Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { PmoaService } from 'src/app/services/emis/pmoa.services';
import { AlertService } from 'src/app/services/alert.service';
import { SqlitedatabaseService } from 'src/app/services/sqlite/sqlitedatabase.service';
import { UserSessionService } from 'src/app/services/usersession.service';

@Component({
  selector: 'app-class-list',
  templateUrl: './class-list.page.html',
  styleUrls: ['./class-list.page.scss'],
})
export class ClassListPage implements OnInit {

  schoolId: any;
  classSecListData: any[];
  filterClass: any[];
  StudentData: any[];
  totalStudent: number;
  filterSec: any[];
  section: any[];
  Sclclassid: any[];
  idData: any;
  SchoolName: any;
  totalStudentData: any;
  totalDataScreen: any;
  totalScrByMe: number;
  totalSchool: any;
  totalScnTech: any;
  totalrefPmoa: any;
  totalscnPmoa: any;
  usernameId: any;

  constructor(
    private router: Router,
    private healthServices: PmoaService,
    private route: ActivatedRoute,
    private sqliteDB: SqlitedatabaseService,
    private alertService: AlertService,
    private usersessionService: UserSessionService,

  ) { }

  ngOnInit() {

  }

  ionViewDidEnter() {
    if (this.route.snapshot.queryParamMap.get("SchoolId")) {
      // this.schoolId = "30206"
      this.schoolId = this.route.snapshot.queryParamMap.get("SchoolId");
      this.SchoolName = this.route.snapshot.queryParamMap.get("SchoolName");
    }
    this.usernameId = this.usersessionService.emis_username();
    console.log('user',this.usernameId)
    this.checkLocalExistClassList()
    this.getTotalClassData()
  }

  // Check Local Data Exist Method_________________________________________________________________________________*
  checkLocalExistClassList() {
    this.sqliteDB.checkDataExistsWithConditions('ClassSec', "SchlId", this.schoolId).then((res) => {
      // console.log("checkDataExistsWithConditions res",res);
      if (res == true) {
        this.getClassLocalDB(); // Local Data
      }
      else {
        if ( this.schoolId) {
          this.getClassSecData();  // From Server
        }
      }
    });
  }

  navigateBack() {
    this.router.navigate(['/tabs/school-list']);
  }

  nextPage(classId, SchoolId) {
    this.router.navigate(['/tabs/section-list'], {
      queryParams: { classId, SchoolId }
    });
  }

  getTotalClassData() {
    this.healthServices.getTotalSchoolCont(this.schoolId).subscribe((response) => {
      this.totalSchool = response.result.TotStuCount[0].Count
      this.totalScnTech = response.result.TotStuScrndCount[0].Count
      this.totalrefPmoa = response.result.TotStuRefrdPmoa[0].Count
      this.totalscnPmoa = response.result.TotStuScrndByPmoa[0].Count
    })
  }

  getClassSecData() {
    this.healthServices.getTotalClassData(this.schoolId).subscribe((response) => {
      this.classSecListData = []
      if(response.dataStatus) {
        response.result.forEach(element => {
          this.saveClassLocalDB(element);
          this.classSecListData = response.result
        });
        this.getClassLocalDB()

        this.classSecListData = response.result
        this.classSecListData = [...new Map(response.result.map(item => [JSON.stringify(item.class_studying_id), item.class_studying_id])).values()];
       let tesstData = this.classSecListData.sort((n1,n2) => n1 - n2);
      this.idData = this.schoolId;
      } else {
        this.alertService.error(response.message);
      }
    })
  }

  getClassLocalDB() {
    let query = 'SELECT Classid as class_studying_id FROM ClassSec' +
      ' WHERE SchlId = "' + this.schoolId + '"';
    return this.sqliteDB.getDataLocalDB(query).then(data => {
      if (data.rows.length > 0) {
        this.classSecListData = [];
        for (var i = 0; i < data.rows.length; i++) {
          this.classSecListData.push(data.rows.item(i));
        }
        this.classSecListData = [...new Map(this.classSecListData.map(item => [JSON.stringify(item.class_studying_id), item.class_studying_id])).values()];
        let tesstData = this.classSecListData.sort((n1,n2) => n1 - n2);
        this.idData = this.schoolId;
      } else {
        // this.getBlocklistServer();
      }
    });
  }

  saveClassLocalDB(element) {
    const datainsert = 'INSERT INTO ClassSec VALUES (?,?,?,?,?,?,?)';
    this.sqliteDB.insert(datainsert, [null, this.schoolId, this.schoolId, element.IndexId, element.screening_date, element.class_section, element.class_studying_id]).then(insertres => {
      if (insertres) {
        // console.log('class info inserted');
      }
    });
  }

  onSync() {
    let query = 'DELETE FROM  ClassSec';
    
      return this.sqliteDB.getDataLocalDB(query).then(data1 => {
      if (data1.rowsAffected > 0) {
        this.getClassSecData();
      }
    });
  }
}
